#!/usr/bin/env python3
import argparse
import json
import sys


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--level", required=True)
    parser.add_argument("case_file")
    args = parser.parse_args()

    matches = []
    try:
        lines = open(args.case_file, "rb").read().splitlines()
        for number, raw_line in enumerate(lines, 1):
            try:
                event = json.loads(raw_line.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                print(f"line {number}: invalid JSON: {error}", file=sys.stderr)
                return 1
            if (
                not isinstance(event, dict)
                or not isinstance(event.get("level"), str)
                or not isinstance(event.get("message"), str)
            ):
                print(
                    f"line {number}: invalid JSON event: expected string level and message fields",
                    file=sys.stderr,
                )
                return 1
            if event["level"] == args.level:
                matches.append(raw_line + b"\n")
    except OSError as error:
        print(error, file=sys.stderr)
        return 1

    sys.stdout.buffer.write(b"".join(matches))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

